let raw = $json.content || "";

// STEP 1: ensure string
if (typeof raw !== "string") {
  raw = String(raw);
}

// STEP 2: remove escaped formatting
raw = raw
  .replace(/\\n/g, "")
  .replace(/\\t/g, "")
  .replace(/\r/g, "")
  .trim();

// STEP 3: extract JSON block
const match = raw.match(/\{[\s\S]*\}/);

if (!match) {
  return [{
    json: {
      isEvent: false,
      error: "No JSON found",
      raw
    }
  }];
}

let cleaned = match[0];

// STEP 4: fix escaped quotes if any
cleaned = cleaned.replace(/\\"/g, '"');

let data;

try {
  data = JSON.parse(cleaned);
} catch (e) {
  return [{
    json: {
      isEvent: false,
      error: "JSON parse failed",
      raw: cleaned
    }
  }];
}

// STEP 5: safety defaults
data.isEvent = data.isEvent ?? false;
data.priority = data.priority ?? "low";

return [{ json: data }];

