// n8n Code Node
// Input = weekly-summary response you pasted
// Cleans duplicates, keeps only active events, limits to actual week,
// and builds AI-ready summary data.

const payload = $json;

// If API returns array with one object
const week = Array.isArray(payload) ? payload[0] : payload;

// Safety fallback
const events = week.events || [];

// Week boundaries
const weekStart = new Date(week.week_start);
const weekEnd = new Date(week.week_end);

// Keep only valid events inside week range + not deleted
const cleaned = events
  .map(e => ({
    title: e[0],
    start: e[1],
    end: e[2],
    category: e[3],
    status: e[4],
    deleted: e[5]
  }))
  .filter(e => {
    const d = new Date(e.start);
    return d >= weekStart && d < weekEnd && e.deleted === false;
  });

// Remove duplicates (same title + same start)
const uniqueMap = {};
for (const e of cleaned) {
  const key = `${e.title}_${e.start}`;
  uniqueMap[key] = e;
}

const unique = Object.values(uniqueMap);

// Stats
let totalMinutes = 0;
const dayCount = {};
const categoryCount = {};

for (const e of unique) {
  const start = new Date(e.start);
  const end = new Date(e.end);

  const mins = Math.round((end - start) / 60000);
  totalMinutes += mins;

  const day = start.toLocaleDateString('en-US', { weekday: 'long' });
  dayCount[day] = (dayCount[day] || 0) + 1;

  categoryCount[e.category] = (categoryCount[e.category] || 0) + 1;
}

// busiest day
let busiestDay = "None";
let max = 0;

for (const d in dayCount) {
  if (dayCount[d] > max) {
    max = dayCount[d];
    busiestDay = d;
  }
}

// Output for Ollama
return [
{
  json: {
    week_start: week.week_start,
    week_end: week.week_end,
    total_events: unique.length,
    total_hours: +(totalMinutes / 60).toFixed(1),
    busiest_day: busiestDay,
    category_breakdown: categoryCount,
    events: unique
  }
}
];

