const rangeStart = new Date($('text to object2').first().json.start);
const rangeEnd = new Date($('text to object2').first().json.end);

// get all calendar items
const events = $input.all().map(i => {
  const e = i.json;

  const start = e.start?.dateTime || e.start?.date;
  const end = e.end?.dateTime || e.end?.date;

  return {
    start: new Date(start),
    end: new Date(end)
  };
});

// sort events
events.sort((a, b) => a.start - b.start);

let freeSlots = [];
let current = new Date(rangeStart);

for (const event of events) {
  // skip events outside range
  if (event.end <= rangeStart || event.start >= rangeEnd) continue;

  const eventStart = new Date(Math.max(event.start, rangeStart));
  const eventEnd = new Date(Math.min(event.end, rangeEnd));

  if (eventStart > current) {
    freeSlots.push({
      start: current.toISOString(),
      end: eventStart.toISOString()
    });
  }

  if (eventEnd > current) {
    current = eventEnd;
  }
}

// last slot
if (current < rangeEnd) {
  freeSlots.push({
    start: current.toISOString(),
    end: rangeEnd.toISOString()
  });
}

return [
  {
    json: {
      free_slots: freeSlots
    }
  }
];

