// INPUT
const sessions = $json.sessions;

// flatten + sort slots
let slots = $json.free_slots
  .map(s => ({
    start: new Date(s.start),
    end: new Date(s.end)
  }))
  .filter(s => s.end > s.start)
  .sort((a, b) => a.start - b.start);

// helpers
function addMinutes(date, min) {
  return new Date(date.getTime() + min * 60000);
}

// build full timeline capacity
let totalDuration = 0;
for (let s of slots) {
  totalDuration += (s.end - s.start);
}

// assign sessions proportionally
let results = [];
let pointer = 0;

for (let i = 0; i < sessions.length; i++) {

  let session = sessions[i];

  // target position in timeline (spread evenly)
  let ratio = i / sessions.length;
  let targetTime = new Date(slots[0].start.getTime() + totalDuration * ratio);

  let found = null;

  for (let slot of slots) {

    let start = new Date(Math.max(slot.start, targetTime));
    start = addMinutes(start, 10); // gap

    let end = addMinutes(start, session.duration);

    if (end <= slot.end) {
      found = { start, end };
      break;
    }
  }

  if (!found) {
    throw new Error("No slot for: " + session.title);
  }

  results.push({
    title: session.title,
    description: session.description,
    start: found.start.toISOString(),
    end: found.end.toISOString()
  });
}

return [{ json: { sessions: results } }];

const events = $input.all().map(i => i.json);

// group by date (Asia/Karachi aware)
function getDateKey(dateStr) {
  const d = new Date(dateStr);
  return d.toLocaleDateString('en-CA', { timeZone: 'Asia/Karachi' }); 
}

// build grouped structure
const grouped = {};

for (const e of events) {

  const start = e.start?.dateTime || e.start?.date;
  const end = e.end?.dateTime || e.end?.date;

  const dateKey = getDateKey(start);

  if (!grouped[dateKey]) {
    grouped[dateKey] = [];
  }

  grouped[dateKey].push({
    title: e.summary,
    description: e.description || "",
    start,
    end
  });
}

// convert to AI-friendly structured format
const schedule = Object.keys(grouped)
  .sort()
  .map(date => ({
    date,
    items: grouped[date].sort((a, b) => new Date(a.start) - new Date(b.start))
  }));

return [
  {
    json: {
      schedule
    }
  }
];

const newEvent = $input.first().json;

const items = $items("Check Duplicate") || [];

// filter REAL calendar events (ignore empty {})
const validEvents = items.filter(e => {
  return e.json &&
         e.json.start &&
         (e.json.start.dateTime || e.json.start);
});

// If no real events → safe to create
if (validEvents.length === 0) {
  return [{
    json: {
      canCreate: true,
      isDuplicate: false,
      reason: "No real events found (empty calendar result)"
    }
  }];
}

// check overlap
function overlap(aStart, aEnd, bStart, bEnd) {
  return new Date(aStart) < new Date(bEnd) &&
         new Date(aEnd) > new Date(bStart);
}

let conflicts = [];

for (const e of validEvents) {
  const start = e.json.start?.dateTime || e.json.start;
  const end = e.json.end?.dateTime || e.json.end;

  if (!start || !end) continue;

  if (overlap(newEvent.start, newEvent.end, start, end)) {
    conflicts.push(e.json);
  }
}

return [{
  json: {
    canCreate: conflicts.length === 0,
    isDuplicate: conflicts.length > 0,
    conflicts,
    event: newEvent
  }
}];
